+    bookName: '',
+    bookDescription: '',
+    bookAuthor: '',
+    reciter: '',
+    category: '',
+    language: '',
+    status: 'isCertified',
+    chapters: [],
+  });
+
+  const [bookCoverUri, setBookCoverUri] = useState(null);
+  const [bookAudioUri, setBookAudioUri] = useState(null);
+  const [loading, setLoading] = useState(type === 'edit');
+  const [error, setError] = useState(null);
+  const [chapterTitle, setChapterTitle] = useState('');
+  const [chapterDuration, setChapterDuration] = useState('');
+  const [chapterAudioUri, setChapterAudioUri] = useState('');
+  
+  const { bookId } = useLocalSearchParams();
+  const apiUrl = Constants.expoConfig?.extra?.API_BASE_URL;
+
+  const backgroundColor = useThemeColor({}, 'background');
+  const textColor = useThemeColor({}, 'text');
+  const primaryColor = useThemeColor({}, 'primary');
+
+  // Fetch existing data in edit mode
+  useEffect(() => {
+    if (type === 'edit' && bookId) {
+      const fetchBook = async () => {
+        try {
+          const token = await SecureStore.getItemAsync('authToken');
+          const response = await axios.get(`${apiUrl}/books/${bookId}`, {
+            headers: {
+              Authorization: `Bearer ${token}`,
+            },
+          });
+          const book = response.data;
+          setFormData({
+            bookName: book.bookName || '',
+            bookDescription: book.bookDescription || '',
+            bookAuthor: book.bookAuthor || '',
+            reciter: book.reciter || '',
+            category: book.category || '',
+            language: book.language || '',
+            chapters: book.chapters || [],
+          });
+          setBookCoverUri(book.bookCover || null);
+          setBookAudioUri(book.bookAudio || null);
+        } catch (err) {
+          setError('Failed to load book details');
+        } finally {
+          setLoading(false);
+        }
+      };
+      fetchBook();
+    }
+  }, [type, bookId]);
+
+  const handleChange = (key, value) => {
+    setFormData((prev) => ({ ...prev, [key]: value }));
+  };
+
+  const handleAddChapter = () => {
+    if (!chapterTitle || !chapterDuration || !chapterAudioUri) {
+      Alert.alert('Error', 'Please fill out all chapter fields');
+      return;
+    }
+    setFormData((prev) => ({
+      ...prev,
+      chapters: [
+        ...prev.chapters,
+        {
+          id: `chap-${prev.chapters.length + 1}`,
+          title: chapterTitle,
+          duration: chapterDuration,
+          audioUrl: chapterAudioUri,
+        },
+      ],
+    }));
+    setChapterTitle('');
+    setChapterDuration('');
+    setChapterAudioUri('');
+  };
+
+  const pickImage = async () => {
+    const result = await ImagePicker.launchImageLibraryAsync({
+      mediaTypes: ImagePicker.MediaTypeOptions.Images,
+      allowsEditing: true,
+      quality: 1,
+    });
+
+    if (!result.canceled) {
+      setBookCoverUri(result.assets[0].uri);
+    }
+  };
+
+  const pickAudio = async () => {
+    const result = await DocumentPicker.getDocumentAsync({
+      type: 'audio/*',
+    });
+
+    if (result.type === 'success') {
+      setBookAudioUri(result.uri);
+    }
+  };
+
+  const handleSubmit = async () => {
+    try {
+      const token = await SecureStore.getItemAsync('authToken');
+      if (!token) throw new Error('No authentication token found');
+
+      const url = type === 'edit'
+        ? `${apiUrl}/updateBook/${bookId}`
+        : `${apiUrl}/addBook`;
+      const method = type === 'edit' ? 'put' : 'post';
+
+      const data = new FormData();
+      Object.keys(formData).forEach((key) => {
+        if (key !== 'chapters') {
+          data.append(key, formData[key]);
+        }
+      });
+
+      if (bookCoverUri && !bookCoverUri.startsWith('http')) {
+        data.append('bookCover', {
+          uri: bookCoverUri,
+          name: 'book-cover.jpg',
+          type: 'image/jpeg',
+        });
+      }
+
+      if (bookAudioUri && !bookAudioUri.startsWith('http')) {
+        data.append('bookAudio', {
+          uri: bookAudioUri,
+          name: 'book-audio.mp3',
+          type: 'audio/mpeg',
+        });
+      }
+
+      await axios({
+        method,
+        url,
+        data,
+        headers: {
+          'Content-Type': 'multipart/form-data',
+          Authorization: `Bearer ${token}`,
+        },
+      });
+
+      Alert.alert('Success', `Book ${type === 'edit' ? 'updated' : 'added'} successfully`);
+    } catch (err) {
+      Alert.alert('Error', err.message || 'Something went wrong');
+    }
+  };
+
+  if (loading) {
+    return (
+      <ThemedView style={tw`flex-1 justify-center items-center`}>
+        <ActivityIndicator size="large" color={primaryColor} />
+      </ThemedView>
+    );
+  }
+
+  return (
+    <ScrollView style={[tw`p-4`, { backgroundColor }]}>
+      <ThemedText style={tw`text-xl mb-4 text-center`} darkColor={textColor}>
+        {type === 'edit' ? 'Edit Book' : 'Add New Book'}
+      </ThemedText>
+
+      {[
+        { key: 'bookName', label: 'Book Name' },
+        { key: 'bookDescription', label: 'Description' },
+        { key: 'bookAuthor', label: 'Author' },
+        { key: 'reciter', label: 'Reciter' },
+        { key: 'category', label: 'Category' },
+        { key: 'language', label: 'Language' },
+      ].map(({ key, label }) => (
+        <TextInput
+          key={key}
+          placeholder={label}
+          value={formData[key]}
+          onChangeText={(text) => handleChange(key, text)}
+          placeholderTextColor={textColor}
+          style={[
+            tw`border rounded p-3 mb-4`,
+            { borderColor: primaryColor, color: textColor },
+          ]}
+        />
+      ))}
+
+      {/* Image Picker */}
+      <TouchableOpacity
+        style={[tw`rounded-xl p-3 mb-4`, { backgroundColor: primaryColor }]}
+        onPress={pickImage}
+      >
+        <ThemedText style={tw`text-white text-center`}>Pick Book Cover Image</ThemedText>
+      </TouchableOpacity>
+
+      {bookCoverUri && (
+        <Image
+          source={{ uri: bookCoverUri }}
+          style={tw`w-full h-48 mb-4 rounded`}
+          resizeMode="cover"
+        />
+      )}
+
+      {/* Audio Picker */}
+      <TouchableOpacity
+        style={[tw`rounded-xl p-3 mb-4`, { backgroundColor: primaryColor }]}
+        onPress={pickAudio}
+      >
+        <ThemedText style={tw`text-white text-center`}>Pick Book Audio File</ThemedText>
+      </TouchableOpacity>
+
+      {bookAudioUri && (
+        <ThemedText style={tw`text-center text-sm mb-4`} darkColor={textColor}>
+          {bookAudioUri.split('/').pop()}
+        </ThemedText>
+      )}
+
+      {/* Chapter Inputs */}
+      <ThemedText style={tw`text-lg mb-4`} darkColor={textColor}>
+        Add Chapters
+      </ThemedText>
+
+      <TextInput
+        placeholder="Chapter Title"
+        value={chapterTitle}
+        onChangeText={setChapterTitle}
+        placeholderTextColor={textColor}
+        style={[
+          tw`border rounded p-3 mb-4`,
+          { borderColor: primaryColor, color: textColor },
+        ]}
+      />
+
+      <TextInput
+        placeholder="Chapter Duration"
+        value={chapterDuration}
+        onChangeText={setChapterDuration}
+        placeholderTextColor={textColor}
+        style={[
+          tw`border rounded p-3 mb-4`,
+          { borderColor: primaryColor, color: textColor },
+        ]}
+      />
+
+      <TouchableOpacity
+        style={[tw`rounded-xl p-3 mb-4`, { backgroundColor: primaryColor }]}
+        onPress={pickAudio}
+      >
+        <ThemedText style={tw`text-white text-center`}>Pick Chapter Audio File</ThemedText>
+      </TouchableOpacity>
+
+      {chapterAudioUri && (
+        <ThemedText style={tw`text-center text-sm mb-4`} darkColor={textColor}>
+          {chapterAudioUri.split('/').pop()}
+        </ThemedText>
+      )}
+
+      <TouchableOpacity
+        style={[tw`rounded-xl p-4 mt-2`, { backgroundColor: primaryColor }]}
+        onPress={handleAddChapter}
+      >
+        <ThemedText style={tw`text-white text-center text-lg font-semibold`}>
+          Add Chapter
+        </ThemedText>
+      </TouchableOpacity>
+
+      {/* Submit */}
+      <TouchableOpacity
+        onPress={handleSubmit}
+        style={[tw`rounded-xl p-4 mt-2`, { backgroundColor: primaryColor }]}
+      >
+        <ThemedText style={tw`text-white text-center text-lg font-semibold`}>
+          {type === 'edit' ? 'Update Book' : 'Add Book'}
+        </ThemedText>
+      </TouchableOpacity>
+    </ScrollView>
+  );
+}

