+import axios from 'axios';
+import Constants from 'expo-constants';
+import { useLocalSearchParams } from 'expo-router';
+import tw from 'twrnc';
+
+import { useThemeColor } from '@/hooks/useThemeColor';
+import { ThemedText } from '@/components/ThemedText';
+import { ThemedView } from '@/components/ThemedView';
+
+export default function BookForm({ type = 'add' }) {
+  const [formData, setFormData] = useState({
+    bookName: '',
+    bookDescription: '',
+    bookAuthor: '',
+    reciter: '',
+    category: '',
+    language: '',
+    status: 'isCertified',
+    chapters: [],
+  });
+
+  const [bookCoverUri, setBookCoverUri] = useState(null);
+  const [bookAudioUri, setBookAudioUri] = useState(null);
+  const [loading, setLoading] = useState(type === 'edit');
+  const [chapterTitle, setChapterTitle] = useState('');
+  const [chapterDuration, setChapterDuration] = useState('');
+  const [chapterAudioUri, setChapterAudioUri] = useState('');
+
+  const { bookId } = useLocalSearchParams();
+  const apiUrl = Constants.expoConfig?.extra?.API_BASE_URL;
+
+  const backgroundColor = useThemeColor({}, 'background');
+  const textColor = useThemeColor({}, 'text');
+  const primaryColor = useThemeColor({}, 'primary');
+
+  useEffect(() => {
+    if (type === 'edit' && bookId) {
+      const fetchBook = async () => {
+        try {
+          const token = await SecureStore.getItemAsync('authToken');
+          const res = await axios.get(`${apiUrl}/books/${bookId}`, {
+            headers: { Authorization: `Bearer ${token}` },
+          });
+          const book = res.data;
+          setFormData({
+            bookName: book.bookName || '',
+            bookDescription: book.bookDescription || '',
+            bookAuthor: book.bookAuthor || '',
+            reciter: book.reciter || '',
+            category: book.category || '',
+            language: book.language || '',
+            status: book.status || 'isCertified',
+            chapters: book.chapters || [],
+          });
+          setBookCoverUri(book.bookCover);
+          setBookAudioUri(book.bookAudio);
+        } catch (err) {
+          Alert.alert('Error', 'Failed to load book details');
+        } finally {
+          setLoading(false);
+        }
+      };
+      fetchBook();
+    }
+  }, [type, bookId]);
+
+  const handleChange = (key, value) => {
+    setFormData((prev) => ({ ...prev, [key]: value }));
+  };
+
+  const pickImage = async () => {
+    const result = await ImagePicker.launchImageLibraryAsync({
+      mediaTypes: ImagePicker.MediaTypeOptions.Images,
+      quality: 1,
+    });
+    if (!result.canceled) {
+      setBookCoverUri(result.assets[0].uri);
+    }
+  };
+
+  const pickAudio = async (setUri) => {
+    const result = await DocumentPicker.getDocumentAsync({ type: 'audio/*' });
+    if (result.type === 'success') {
+      setUri(result.uri);
+    }
+  };
+
+  const handleAddChapter = () => {
+    if (!chapterTitle || !chapterDuration || !chapterAudioUri) {
+      Alert.alert('Error', 'Fill in all chapter fields');
+      return;
+    }
+
+    const newChapter = {
+      id: `chap-${formData.chapters.length + 1}`,
+      title: chapterTitle,
+      duration: chapterDuration,
+      audioUrl: chapterAudioUri,
+    };
+
+    setFormData((prev) => ({
+      ...prev,
+      chapters: [...prev.chapters, newChapter],
+    }));
+
+    setChapterTitle('');
+    setChapterDuration('');
+    setChapterAudioUri('');
+  };
+
+  const handleSubmit = async () => {
+    try {
+      const token = await SecureStore.getItemAsync('authToken');
+      const form = new FormData();
+
+      Object.entries(formData).forEach(([key, value]) => {
+        if (key === 'chapters') {
+          form.append('chapters', JSON.stringify(value));
+        } else {
+          form.append(key, value);
+        }
+      });
+
+      if (bookCoverUri && !bookCoverUri.startsWith('http')) {
+        form.append('bookCover', {
+          uri: bookCoverUri,
+          name: 'cover.jpg',
+          type: 'image/jpeg',
+        });
+      }
+
+      if (bookAudioUri && !bookAudioUri.startsWith('http')) {
+        form.append('bookAudio', {
+          uri: bookAudioUri,
+          name: 'audio.mp3',
+          type: 'audio/mpeg',
+        });
+      }
+
+      const url =
+        type === 'edit'
+          ? `${apiUrl}/updateBook/${bookId}`
+          : `${apiUrl}/addBook`;
+
+      await axios({
+        method: type === 'edit' ? 'put' : 'post',
+        url,
+        data: form,
+        headers: {
+          'Content-Type': 'multipart/form-data',
+          Authorization: `Bearer ${token}`,
+        },
+      });
+
+      Alert.alert('Success', `Book ${type === 'edit' ? 'updated' : 'added'}!`);
+    } catch (err) {
+      Alert.alert('Error', err.message || 'Submission failed');
+    }
+  };
+
+  if (loading) {
+    return (
+      <ThemedView style={tw`flex-1 justify-center items-center`}>
+        <ActivityIndicator size="large" color={primaryColor} />
+      </ThemedView>
+    );
+  }
+
+  return (
+    <ScrollView style={[tw`p-4`, { backgroundColor }]}>
+      <ThemedText style={tw`text-xl mb-4 text-center`}>
+        {type === 'edit' ? 'Edit Book' : 'Add Book'}
+      </ThemedText>
+
+      {[
+        { key: 'bookName', label: 'Book Name' },
+        { key: 'bookDescription', label: 'Description' },
+        { key: 'bookAuthor', label: 'Author' },
+        { key: 'reciter', label: 'Reciter' },
+        { key: 'category', label: 'Category' },
+        { key: 'language', label: 'Language' },
+      ].map(({ key, label }) => (
+        <TextInput
+          key={key}
+          placeholder={label}
+          value={formData[key]}
+          onChangeText={(text) => handleChange(key, text)}
+          style={tw`border mb-3 p-2 rounded`}
+        />
+      ))}
+
+      <TouchableOpacity style={tw`mb-3`} onPress={pickImage}>
+        <Text style={tw`text-blue-600`}>Select Book Cover Image</Text>
+        {bookCoverUri && (
+          <Image
+            source={{ uri: bookCoverUri }}
+            style={tw`w-32 h-32 mt-2 rounded`}
+          />
+        )}
+      </TouchableOpacity>
+
+      <TouchableOpacity style={tw`mb-3`} onPress={() => pickAudio(setBookAudioUri)}>
+        <Text style={tw`text-blue-600`}>Select Book Audio</Text>
+        {bookAudioUri && (
+          <Text style={tw`text-green-600 mt-1`}>Audio Selected</Text>
+        )}
+      </TouchableOpacity>
+
+      <ThemedText style={tw`text-lg mt-5 mb-2`}>Add Chapter</ThemedText>
+
+      <TextInput
+        placeholder="Chapter Title"
+        value={chapterTitle}
+        onChangeText={setChapterTitle}
+        style={tw`border mb-2 p-2 rounded`}
+      />
+      <TextInput
+        placeholder="Duration (e.g., 05:30)"
+        value={chapterDuration}
+        onChangeText={setChapterDuration}
+        style={tw`border mb-2 p-2 rounded`}
+      />
+      <TouchableOpacity
+        onPress={() => pickAudio(setChapterAudioUri)}
+        style={tw`mb-2`}
+      >
+        <Text style={tw`text-blue-600`}>Pick Chapter Audio</Text>
+        {chapterAudioUri && (
+          <Text style={tw`text-green-600 mt-1`}>Audio Selected</Text>
+        )}
+      </TouchableOpacity>
